import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';

const Navbar = () => {
    const { user, isAuthenticated, logout } = useAuth();
    const navigate = useNavigate();

    const handleLogout = () => {
        logout();
        navigate('/');
    };

    return (
        <nav className="bg-gradient-to-r from-purple-600 to-blue-600 text-white shadow-lg">
            <div className="container mx-auto px-4">
                <div className="flex justify-between items-center h-16">
                    <Link to="/" className="text-2xl font-bold hover:text-gray-200 transition">
                        EventHub
                    </Link>

                    <div className="flex items-center space-x-6">
                        <Link to="/events" className="hover:text-gray-200 transition">
                            Browse Events
                        </Link>
                        
                        {isAuthenticated ? (
                            <>
                                <Link to="/dashboard" className="hover:text-gray-200 transition">
                                    Dashboard
                                </Link>
                                <div className="flex items-center space-x-4">
                                    <span className="text-sm">
                                        Hello, {user?.name}
                                    </span>
                                    <button
                                        onClick={handleLogout}
                                        className="bg-red-500 px-4 py-2 rounded-lg hover:bg-red-600 transition"
                                    >
                                        Logout
                                    </button>
                                </div>
                            </>
                        ) : (
                            <div className="flex items-center space-x-4">
                                <Link
                                    to="/login"
                                    className="bg-white text-purple-600 px-4 py-2 rounded-lg hover:bg-gray-100 transition"
                                >
                                    Login
                                </Link>
                                <Link
                                    to="/register"
                                    className="bg-green-500 px-4 py-2 rounded-lg hover:bg-green-600 transition"
                                >
                                    Register
                                </Link>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </nav>
    );
};

export default Navbar;
